import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.BXzK3EA4.js";const q=JSON.parse('{"title":"一、酒会活动","description":"","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/01-酒会活动.md","filePath":"副业/保险展业/01-酒会活动.md","lastUpdated":1792941182000}'),d={name:"副业/保险展业/01-酒会活动.md"};function o(r,t,h,s,n,u){return e(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="一、酒会活动" tabindex="-1">一、酒会活动 <a class="header-anchor" href="#一、酒会活动" aria-label="Permalink to &quot;一、酒会活动&quot;">​</a></h1><p>参加客户活动（品鉴会、酒会、沙龙等）是保险代理人接触潜在客户的重要场合。</p><h2 id="_1-活动类型" tabindex="-1">1. 活动类型 <a class="header-anchor" href="#_1-活动类型" aria-label="Permalink to &quot;1. 活动类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>场景</th><th>目的</th></tr></thead><tbody><tr><td>品鉴会</td><td>红酒/茶叶/珠宝品鉴</td><td>高净值人群，圈层获客</td></tr><tr><td>健康沙龙</td><td>养生讲座、体检报告解读</td><td>健康类保险切入点</td></tr><tr><td>亲子活动</td><td>亲子手工、生日会</td><td>家长群体，家庭险切入点</td></tr><tr><td>财富讲座</td><td>理财分享、经济形势分析</td><td>储蓄险/投资险切入点</td></tr><tr><td>节庆活动</td><td>中秋/端午/年会</td><td>老客户维护 + 转介绍</td></tr></tbody></table><h2 id="_2-参加前准备" tabindex="-1">2. 参加前准备 <a class="header-anchor" href="#_2-参加前准备" aria-label="Permalink to &quot;2. 参加前准备&quot;">​</a></h2><h3 id="形象" tabindex="-1">形象 <a class="header-anchor" href="#形象" aria-label="Permalink to &quot;形象&quot;">​</a></h3><ul><li>着装得体，符合活动调性（品鉴会穿正式点，沙龙可以偏商务休闲）</li><li>名片备足（电子名片+纸质名片）</li><li>公司宣传页/名片夹</li></ul><h3 id="物料" tabindex="-1">物料 <a class="header-anchor" href="#物料" aria-label="Permalink to &quot;物料&quot;">​</a></h3><ul><li>公司官方产品单页（可放置于现场展示台）</li><li>个人名片</li><li>预约卡（现场填写联系方式用）</li></ul><h3 id="心态" tabindex="-1">心态 <a class="header-anchor" href="#心态" aria-label="Permalink to &quot;心态&quot;">​</a></h3><ul><li><strong>不是去卖保险，是去交朋友</strong></li><li>前 3 次见面不提保险，先建立信任</li><li>目标：拿到 3-5 个有效联系方式</li></ul><h2 id="_3-现场执行" tabindex="-1">3. 现场执行 <a class="header-anchor" href="#_3-现场执行" aria-label="Permalink to &quot;3. 现场执行&quot;">​</a></h2><h3 id="破冰话术" tabindex="-1">破冰话术 <a class="header-anchor" href="#破冰话术" aria-label="Permalink to &quot;破冰话术&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;您好，我是朋友介绍过来的，请问您是从事什么行业的？&quot;</span></span>
<span class="line"><span>&quot;今天这个活动您觉得怎么样？&quot;</span></span></code></pre></div><h3 id="倾听优先" tabindex="-1">倾听优先 <a class="header-anchor" href="#倾听优先" aria-label="Permalink to &quot;倾听优先&quot;">​</a></h3><ul><li>多问开放式问题：<code>&quot;您平时怎么安排家庭的保障规划的？&quot;</code></li><li>少说多听，记录客户提到的关键词（孩子教育、养老、房产等）</li><li>找共同点拉近距离</li></ul><h3 id="识别需求信号" tabindex="-1">识别需求信号 <a class="header-anchor" href="#识别需求信号" aria-label="Permalink to &quot;识别需求信号&quot;">​</a></h3><ul><li>提到&quot;孩子&quot;、&quot;教育&quot;→ 教育金/少儿险</li><li>提到&quot;养老&quot;、&quot;退休&quot;→ 养老险</li><li>提到&quot;看病&quot;、&quot;住院&quot;→ 医疗险/重疾险</li><li>提到&quot;房贷&quot;、&quot;压力&quot;→ 定期寿险/意外险</li><li>提到&quot;理财&quot;、&quot;存款&quot;→ 储蓄险</li></ul><h3 id="临别收口" tabindex="-1">临别收口 <a class="header-anchor" href="#临别收口" aria-label="Permalink to &quot;临别收口&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;今天聊得很开心，方便加个微信吗？后续有相关的内容我再分享给您。&quot;</span></span></code></pre></div><p>不要现场就讲产品，先建立联系。</p><h2 id="_4-参加后跟进" tabindex="-1">4. 参加后跟进 <a class="header-anchor" href="#_4-参加后跟进" aria-label="Permalink to &quot;4. 参加后跟进&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>动作</th></tr></thead><tbody><tr><td>当天或次日</td><td>发微信感谢，表达很高兴认识</td></tr><tr><td>3天内</td><td>发一条价值内容（文章/资讯）给所有人</td></tr><tr><td>1-2周</td><td>单独私信，对有兴趣的深入聊</td></tr><tr><td>1个月</td><td>邀约一对一面谈</td></tr></tbody></table><h2 id="_5-注意事项" tabindex="-1">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to &quot;5. 注意事项&quot;">​</a></h2><ul><li>❌ 不要现场讲产品算收益，容易让人反感</li><li>❌ 不要贬低其他保险公司或产品</li><li>❌ 不要急于成交，活动场合适合建立关系，不适合深度沟通</li><li>✅ 真诚专业，分享有价值的信息</li><li>✅ 记住客户的名字和职业，下次见面能叫出来</li></ul>`,25)])])}const b=a(d,[["render",o]]);export{q as __pageData,b as default};
